import { useId } from "react";

import {
  CALILEON_GRADIENT,
  CALILEON_MARK_EYE,
  CALILEON_MARK_PATH,
  CALILEON_MARK_VIEWBOX,
  CALILEON_WORDMARK_EMBOLDEN,
  CALILEON_WORDMARK_PATH,
  CALILEON_WORDMARK_VIEWBOX,
} from "./calileonLogoPaths";

import "./ExcalidrawLogo.scss";

// Calileon mark; source and raster set are generated by scripts/brand/build.mjs
const LogoIcon = () => {
  // unique per instance: a shared id breaks when the first copy is hidden
  const gradientId = `calileon-logo-${useId().replace(/:/g, "")}`;
  return (
    <svg
      viewBox={CALILEON_MARK_VIEWBOX}
      xmlns="http://www.w3.org/2000/svg"
      className="ExcalidrawLogo-icon"
      aria-hidden="true"
    >
      <defs>
        <linearGradient
          id={gradientId}
          x1="420"
          y1="70"
          x2="120"
          y2="470"
          gradientUnits="userSpaceOnUse"
        >
          {CALILEON_GRADIENT.map(([offset, color]) => (
            <stop
              key={offset}
              offset={offset}
              // the tail stop is themed via --color-logo-tail
              style={{
                stopColor:
                  offset === 1 ? `var(--color-logo-tail, ${color})` : color,
              }}
            />
          ))}
        </linearGradient>
      </defs>
      <path d={CALILEON_MARK_PATH} fill={`url(#${gradientId})`} />
      <circle
        cx={CALILEON_MARK_EYE.cx}
        cy={CALILEON_MARK_EYE.cy}
        r={CALILEON_MARK_EYE.r}
        fill="#fff"
      />
      <circle
        cx={CALILEON_MARK_EYE.cx}
        cy={CALILEON_MARK_EYE.cy}
        r={CALILEON_MARK_EYE.pupil}
        fill={CALILEON_GRADIENT[3][1]}
      />
    </svg>
  );
};

const LogoText = () => (
  <svg
    viewBox={CALILEON_WORDMARK_VIEWBOX}
    xmlns="http://www.w3.org/2000/svg"
    className="ExcalidrawLogo-text"
    role="img"
    aria-label="Calileon"
  >
    <path
      d={CALILEON_WORDMARK_PATH}
      fill="currentColor"
      stroke="currentColor"
      strokeWidth={CALILEON_WORDMARK_EMBOLDEN}
      strokeLinejoin="round"
    />
  </svg>
);

type LogoSize = "xs" | "small" | "normal" | "large" | "custom" | "mobile";

interface LogoProps {
  size?: LogoSize;
  withText?: boolean;
  style?: React.CSSProperties;
  /**
   * If true, the logo will not be wrapped in a Link component.
   * The link prop will be ignored as well.
   * It will merely be a plain div.
   */
  isNotLink?: boolean;
}

export const ExcalidrawLogo = ({
  style,
  size = "small",
  withText,
}: LogoProps) => {
  return (
    <div className={`ExcalidrawLogo is-${size}`} style={style}>
      <LogoIcon />
      {withText && <LogoText />}
    </div>
  );
};
